/**
 * How Three Chinese round fans with swords (`mitsu-ken-kara-uchiwa`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/mitsu-ken-kara-uchiwa";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Three scroll-edged fans point away from a round hub. Small ruled swords fill the three spaces between them. The fans and swords are each set 120 degrees apart.","ja":"丸い中心から、縁の巻いた唐団扇を三つ外へ向けます。団扇の間に、直線で作った剣を三つ置きます。団扇も剣も120度ずつ間をあけます。"};

export default construction;
export { construction, description };
